    public required bool Fits { get; init; }

    /// <summary>
    /// Human-readable explanations, one per limiting or notable factor.
    /// </summary>
    public required IReadOnlyList<string> Reasons { get; init; }

    /// <summary>
    /// Expected wait before the job fits, when the daemon can estimate it.
    /// </summary>
    public ulong? WaitEstimateSecs { get; init; }
}

/// <summary>
/// Decodes an enum from its serde name only, never from a number.
/// </summary>
public sealed class StrictEnumConverter<TEnum> : JsonStringEnumConverter<TEnum>
    where TEnum : struct, System.Enum
{
    /// <summary>
    /// Creates the converter with integer values turned off.
    /// </summary>
    public StrictEnumConverter()
        : base(namingPolicy: null, allowIntegerValues: false)
    {
    }
}

